DARK_STYLESHEET = "QWidget { background: #0B0D18; color: #E8EAFB; font-family: \"Segoe UI\"; font-size: 13px; }\nQMainWindow { background: #090B14; }\nQLabel#hero { font-size: 27px; font-weight: 800; color: #F2F3FF; padding: 10px 0; }\nQLabel#subtitle { color: #929AB9; font-size: 12px; padding-bottom: 12px; }\nQLabel#stat { background: #161B30; border: 1px solid #303755; border-radius: 14px; padding: 16px; font-size: 16px; font-weight: 700; }\nQPushButton { background: #202640; color: #EAF1FF; border: 1px solid #414C70; border-radius: 10px; padding: 12px 16px; font-weight: 650; }\nQPushButton:hover { background: #313B60; border: 1px solid #00E5FF; }\nQPushButton:pressed { background: #141B31; }\nQPushButton#primary { background: #00CBEA; color: #06101B; border: 1px solid #67F4FF; }\nQPushButton#primary:hover { background: #5AF3FF; }\nQPushButton#purple { background: #743BE1; color: white; border: 1px solid #AE85FF; }\nQPushButton#purple:hover { background: #9259F5; }\nQPushButton#pink { background: #462039; color: #FF8DC8; border: 1px solid #B84D88; }\nQTableWidget { background: #111629; alternate-background-color: #171D33; gridline-color: #29314D; border: 1px solid #313956; border-radius: 12px; selection-background-color: #493B85; selection-color: white; }\nQHeaderView::section { background: #202740; color: #00E5FF; padding: 12px; border: none; border-right: 1px solid #303853; font-weight: 700; }\nQLineEdit, QTextEdit { background: #161C31; color: #F4F5FF; border: 1px solid #465074; border-radius: 8px; padding: 8px; selection-background-color: #743BE1; }\nQLineEdit:focus, QTextEdit:focus { border: 1px solid #00E5FF; }\nQDialog { background: #0D1020; }\nQDialogButtonBox QPushButton { min-width: 100px; }\nQScrollBar:vertical { background: #101529; width: 10px; }\nQScrollBar::handle:vertical { background: #4C567E; border-radius: 5px; }\n"
